body({reply, fsync, ok}) ->
    {51, <<>>};
body({lock, Fid, Type, Flags, Start, Length, ProcId, ClientId}) ->
    case is_fid(Fid)
            andalso is_u8(Type)
            andalso is_u32(Flags)
            andalso is_u64(Start)
            andalso is_u64(Length)
            andalso is_u32(ProcId)
            andalso is_string(ClientId) of
        true ->
            {52, <<Fid:32/little, Type:8, Flags:32/little, Start:64/little, Length:64/little,
               ProcId:32/little, (byte_size(ClientId)):16/little, ClientId/binary>>};
        false ->
            invalid
    end;
body({reply, lock, {ok, Status}}) ->
    case is_u8(Status) of
        true ->
            {53, <<Status:8>>};
        false ->
            invalid
    end;
body({getlock, Fid, Type, Start, Length, ProcId, ClientId}) ->
    case is_fid(Fid)
            andalso is_u8(Type)
            andalso is_u64(Start)
            andalso is_u64(Length)
            andalso is_u32(ProcId)
            andalso is_string(ClientId) of
        true ->
            {54, <<Fid:32/little, Type:8, Start:64/little, Length:64/little, ProcId:32/little,
               (byte_size(ClientId)):16/little, ClientId/binary>>};
        false ->
            invalid
    end;
body({reply, getlock, {ok, Type, Start, Length, ProcId, ClientId}}) ->
    case is_u8(Type)
            andalso is_u64(Start)
            andalso is_u64(Length)
            andalso is_u32(ProcId)
            andalso is_string(ClientId) of
        true ->
            {55, <<Type:8, Start:64/little, Length:64/little, ProcId:32/little,
               (byte_size(ClientId)):16/little, ClientId/binary>>};
        false ->
            invalid
    end;
body({link, Dfid, Fid, Name}) ->
    case is_fid(Dfid)
            andalso is_fid(Fid)
            andalso is_name(Name) of
        true ->
            {70, <<Dfid:32/little, Fid:32/little, (byte_size(Name)):16/little, Name/binary>>};
        false ->
            invalid
    end;
body({reply, link, ok}) ->
    {71, <<>>};
body({mkdir, Dfid, Name, Mode, Gid}) ->
    case is_fid(Dfid)
            andalso is_name(Name)
            andalso is_u32(Mode)
            andalso is_u32(Gid) of
        true ->
            {72, <<Dfid:32/little, (byte_size(Name)):16/little, Name/binary, Mode:32/little,
               Gid:32/little>>};
        false ->
            invalid
    end;
body({reply, mkdir, {ok, Qid}}) ->
    case is_qid(Qid) of
        true ->
            {73, <<(put_qid(Qid))/binary>>};
        false ->
            invalid
    end;
body({renameat, OldDirFid, OldName, NewDirFid, NewName}) ->
    case is_fid(OldDirFid)
            andalso is_name(OldName)
            andalso is_fid(NewDirFid)
            andalso is_name(NewName) of
        true ->
            {74, <<OldDirFid:32/little, (byte_size(OldName)):16/little, OldName/binary,
               NewDirFid:32/little, (byte_size(NewName)):16/little, NewName/binary>>};
        false ->
            invalid
    end;
body({reply, renameat, ok}) ->
    {75, <<>>};
body({unlinkat, DirFid, Name, Flags}) ->
    case is_fid(DirFid)
            andalso is_name(Name)
            andalso is_unlink_flags(Flags) of
        true ->
            {76, <<DirFid:32/little, (byte_size(Name)):16/little, Name/binary, Flags:32/little>>};
        false ->
            invalid
    end;
body({reply, unlinkat, ok}) ->
    {77, <<>>};
body({version, Msize, Version}) ->
    case is_u32(Msize)
            andalso is_string(Version) of
        true ->
            {100, <<Msize:32/little, (byte_size(Version)):16/little, Version/binary>>};
        false ->
            invalid
    end;
body({reply, version, {ok, Msize, Version}}) ->
    case is_u32(Msize)
            andalso is_string(Version) of
        true ->
            {101, <<Msize:32/little, (byte_size(Version)):16/little, Version/binary>>};
        false ->
            invalid
    end;
body({auth, Afid, Uname, Aname, NUname}) ->
    case is_u32(Afid)
            andalso is_string(Uname)
            andalso is_string(Aname)
            andalso is_u32(NUname) of
        true ->
            {102, <<Afid:32/little, (byte_size(Uname)):16/little, Uname/binary,
               (byte_size(Aname)):16/little, Aname/binary, NUname:32/little>>};
        false ->
            invalid
    end;
body({attach, Fid, Afid, Uname, Aname, NUname}) ->
    case is_fid(Fid)
            andalso is_u32(Afid)
            andalso is_string(Uname)
            andalso is_string(Aname)
            andalso is_u32(NUname) of
        true ->
            {104, <<Fid:32/little, Afid:32/little, (byte_size(Uname)):16/little, Uname/binary,
               (byte_size(Aname)):16/little, Aname/binary, NUname:32/little>>};
        false ->
            invalid
    end;
body({reply, attach, {ok, Qid}}) ->
    case is_qid(Qid) of
        true ->
            {105, <<(put_qid(Qid))/binary>>};
        false ->
            invalid
    end;
body({flush, OldTag}) ->
    case is_u16(OldTag) of
        true ->
            {108, <<OldTag:16/little>>};
        false ->
            invalid
    end;
body({reply, flush, ok}) ->
    {109, <<>>};
body({walk, Fid, NewFid, Names}) ->
    case is_fid(Fid)
            andalso is_fid(NewFid)
            andalso is_walk_names(Names) of
        true ->
            {110, <<Fid:32/little, NewFid:32/little, (put_walk_names(Names))/binary>>};
        false ->
            invalid
    end;
body({reply, walk, {ok, Qids}}) ->
    case is_qids(Qids) of
        true ->
            {111, <<(put_qids(Qids))/binary>>};
        false ->
            invalid
    end;
body({read, Fid, Offset, Count}) ->
    case is_fid(Fid)
            andalso is_u64(Offset)
            andalso is_io_count(Count) of
        true ->
            {116, <<Fid:32/little, Offset:64/little, Count:32/little>>};
        false ->
            invalid
    end;
body({reply, read, {ok, Data}}) ->
    case is_data(Data) of
        true ->
            {117, <<(byte_size(Data)):32/little, Data/binary>>};
        false ->
            invalid
    end;
body({write, Fid, Offset, Data}) ->
    case is_fid(Fid)
            andalso is_u64(Offset)
            andalso is_data(Data) of
        true ->
            {118, <<Fid:32/little, Offset:64/little, (byte_size(Data)):32/little, Data/binary>>};
        false ->
            invalid
    end;
body({reply, write, {ok, Count, At}}) ->
    case is_u32(Count)
            andalso is_at(At) of
        true ->
            {119, <<Count:32/little>>};
        false ->
            invalid
    end;
body({clunk, Fid}) ->
    case is_fid(Fid) of
        true ->
            {120, <<Fid:32/little>>};
        false ->
            invalid
    end;
body({reply, clunk, ok}) ->
    {121, <<>>};
body({remove, Fid}) ->
    case is_fid(Fid) of
        true ->
            {122, <<Fid:32/little>>};
        false ->
            invalid
    end;
body({reply, remove, ok}) ->
    {123, <<>>};
body(_) ->
    invalid.

%% The fids of a request term, in request order, each with what it names.
-spec fids(tuple()) -> [{directory | node | new, non_neg_integer()}].
fids({statfs, Fid}) ->
    [{node, Fid}];
fids({lopen, Fid, _}) ->
    [{node, Fid}];
fids({lcreate, Fid, _, _, _, _}) ->
    [{directory, Fid}];
fids({symlink, Fid, _, _, _}) ->
    [{directory, Fid}];
fids({mknod, Dfid, _, _, _, _, _}) ->
    [{directory, Dfid}];
fids({readlink, Fid}) ->
    [{node, Fid}];
fids({getattr, Fid, _}) ->
    [{node, Fid}];
fids({setattr, Fid, _}) ->
    [{node, Fid}];
fids({xattrwalk, Fid, NewFid, _}) ->
    [{node, Fid}, {new, NewFid}];
fids({xattrcreate, Fid, _, _, _}) ->
    [{node, Fid}];
fids({readdir, Fid, _, _}) ->
    [{directory, Fid}];
fids({fsync, Fid, _}) ->
    [{node, Fid}];
fids({lock, Fid, _, _, _, _, _, _}) ->
    [{node, Fid}];
fids({getlock, Fid, _, _, _, _, _}) ->
    [{node, Fid}];
fids({link, Dfid, Fid, _}) ->
    [{directory, Dfid}, {node, Fid}];
fids({mkdir, Dfid, _, _, _}) ->
    [{directory, Dfid}];
fids({renameat, OldDirFid, _, NewDirFid, _}) ->
    [{directory, OldDirFid}, {directory, NewDirFid}];
fids({unlinkat, DirFid, _, _}) ->
    [{directory, DirFid}];
fids({version, _, _}) ->
    [];
fids({auth, _, _, _, _}) ->
    [];
fids({attach, Fid, _, _, _, _}) ->
    [{new, Fid}];
fids({flush, _}) ->
    [];
fids({walk, Fid, NewFid, _}) ->
    [{node, Fid}, {new, NewFid}];
fids({read, Fid, _, _}) ->
    [{node, Fid}];
fids({write, Fid, _, _}) ->
    [{node, Fid}];
fids({clunk, Fid}) ->
    [{node, Fid}];
fids({remove, Fid}) ->
    [{node, Fid}].

%% A request term with each of its fids replaced by Fun(Fid).
-spec map_fids(fun((non_neg_integer()) -> non_neg_integer()), tuple()) -> tuple().
map_fids(Fun, {statfs, Fid}) ->
    {statfs, Fun(Fid)};
map_fids(Fun, {lopen, Fid, Flags}) ->
    {lopen, Fun(Fid), Flags};
map_fids(Fun, {lcreate, Fid, Name, Flags, Mode, Gid}) ->
    {lcreate, Fun(Fid), Name, Flags, Mode, Gid};
map_fids(Fun, {symlink, Fid, Name, Target, Gid}) ->
    {symlink, Fun(Fid), Name, Target, Gid};
map_fids(Fun, {mknod, Dfid, Name, Mode, Major, Minor, Gid}) ->
    {mknod, Fun(Dfid), Name, Mode, Major, Minor, Gid};
map_fids(Fun, {readlink, Fid}) ->
    {readlink, Fun(Fid)};
map_fids(Fun, {getattr, Fid, RequestMask}) ->
    {getattr, Fun(Fid), RequestMask};
map_fids(Fun, {setattr, Fid, Attr}) ->
    {setattr, Fun(Fid), Attr};
map_fids(Fun, {xattrwalk, Fid, NewFid, Name}) ->
    {xattrwalk, Fun(Fid), Fun(NewFid), Name};
map_fids(Fun, {xattrcreate, Fid, Name, Size, Flags}) ->
    {xattrcreate, Fun(Fid), Name, Size, Flags};
map_fids(Fun, {readdir, Fid, Offset, Count}) ->
    {readdir, Fun(Fid), Offset, Count};
map_fids(Fun, {fsync, Fid, Datasync}) ->
    {fsync, Fun(Fid), Datasync};
map_fids(Fun, {lock, Fid, Type, Flags, Start, Length, ProcId, ClientId}) ->
    {lock, Fun(Fid), Type, Flags, Start, Length, ProcId, ClientId};
map_fids(Fun, {getlock, Fid, Type, Start, Length, ProcId, ClientId}) ->
    {getlock, Fun(Fid), Type, Start, Length, ProcId, ClientId};
map_fids(Fun, {link, Dfid, Fid, Name}) ->
    {link, Fun(Dfid), Fun(Fid), Name};
map_fids(Fun, {mkdir, Dfid, Name, Mode, Gid}) ->
    {mkdir, Fun(Dfid), Name, Mode, Gid};
map_fids(Fun, {renameat, OldDirFid, OldName, NewDirFid, NewName}) ->
    {renameat, Fun(OldDirFid), OldName, Fun(NewDirFid), NewName};
map_fids(Fun, {unlinkat, DirFid, Name, Flags}) ->
    {unlinkat, Fun(DirFid), Name, Flags};
map_fids(_Fun, {version, Msize, Version}) ->
    {version, Msize, Version};
map_fids(_Fun, {auth, Afid, Uname, Aname, NUname}) ->
    {auth, Afid, Uname, Aname, NUname};
map_fids(Fun, {attach, Fid, Afid, Uname, Aname, NUname}) ->
    {attach, Fun(Fid), Afid, Uname, Aname, NUname};
map_fids(_Fun, {flush, OldTag}) ->
    {flush, OldTag};
map_fids(Fun, {walk, Fid, NewFid, Names}) ->
    {walk, Fun(Fid), Fun(NewFid), Names};
map_fids(Fun, {read, Fid, Offset, Count}) ->
    {read, Fun(Fid), Offset, Count};
map_fids(Fun, {write, Fid, Offset, Data}) ->
    {write, Fun(Fid), Offset, Data};
map_fids(Fun, {clunk, Fid}) ->
    {clunk, Fun(Fid)};
map_fids(Fun, {remove, Fid}) ->
    {remove, Fun(Fid)}.

%% Whether Operation is an operation of the table, or error: an error reply may
%% answer any operation.
known_operation(Operation) ->
    lists:member(Operation, [error, statfs, lopen, lcreate, symlink, mknod, readlink,
                             getattr, setattr, xattrwalk, xattrcreate, readdir, fsync, lock,
                             getlock, link, mkdir, renameat, unlinkat, version, auth, attach,
                             flush, walk, read, write, clunk, remove]).

%% Linux's number of each error of the table, which Rlerror carries, and none for any
%% other term.
errno(enoent) ->
    2;
errno(eacces) ->
    13;
errno(eperm) ->
    1;
errno(eexist) ->
    17;
errno(enotdir) ->
    20;
errno(eisdir) ->
    21;
errno(enotempty) ->
    39;
errno(erofs) ->
    30;
errno(enospc) ->
    28;
errno(efbig) ->
    27;
errno(einval) ->
    22;
errno(ebadf) ->
    9;
errno(emfile) ->
    24;
errno(enfile) ->
    23;
errno(eio) ->
    5;
errno(enametoolong) ->
    36;
errno(enotsup) ->
    95;
errno(eloop) ->
    40;
errno(enxio) ->
    6;
errno(exdev) ->
    18;
errno(enomem) ->
    12;
errno(eagain) ->
    11;
errno(enodata) ->
    61;
errno(erange) ->
    34;
errno(enolck) ->
    37;
errno(_) ->
    none.

%% The error of a number Rlerror carries; a number of no error of the table, as a
%% server answers in another system's numbering, reads as eio.
posix(2) ->
    enoent;
posix(13) ->
    eacces;
posix(1) ->
    eperm;
posix(17) ->
    eexist;
posix(20) ->
    enotdir;
posix(21) ->
    eisdir;
posix(39) ->
    enotempty;
posix(30) ->
    erofs;
posix(28) ->
    enospc;
posix(27) ->
    efbig;
posix(22) ->
    einval;
posix(9) ->
    ebadf;
posix(24) ->
    emfile;
posix(23) ->
    enfile;
posix(5) ->
    eio;
posix(36) ->
    enametoolong;
posix(95) ->
    enotsup;
posix(40) ->
    eloop;
posix(6) ->
    enxio;
posix(18) ->
    exdev;
posix(12) ->
    enomem;
posix(11) ->
    eagain;
posix(61) ->
    enodata;
posix(34) ->
    erange;
posix(37) ->
    enolck;
posix(_) ->
    eio.

%% Each kind read from the front of the bytes: {ok, Value, Rest} or error.
get_u8(<<Value:8, Rest/binary>>) ->
    {ok, Value, Rest};
get_u8(_) ->
    error.

get_u16(<<Value:16/little, Rest/binary>>) ->
    {ok, Value, Rest};
get_u16(_) ->
    error.

get_u32(<<Value:32/little, Rest/binary>>) ->
    {ok, Value, Rest};
get_u32(_) ->
    error.

get_u64(<<Value:64/little, Rest/binary>>) ->
    {ok, Value, Rest};
get_u64(_) ->
    error.

get_fid(<<Value:32/little, Rest/binary>>) ->
    checked(is_fid(Value), Value, Rest);
get_fid(_) ->
    error.

get_io_count(<<Value:32/little, Rest/binary>>) ->
    checked(is_io_count(Value), Value, Rest);
get_io_count(_) ->
    error.

get_xattr_size(<<Value:64/little, Rest/binary>>) ->
    checked(is_xattr_size(Value), Value, Rest);
get_xattr_size(_) ->
    error.

get_unlink_flags(<<Value:32/little, Rest/binary>>) ->
    checked(is_unlink_flags(Value), Value, Rest);
get_unlink_flags(_) ->
    error.

get_at(Bin0) ->
    {ok, unknown, Bin0}.

get_name(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_name(Value), Value, Rest);
get_name(_) ->
    error.

get_walk_name(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_walk_name(Value), Value, Rest);
get_walk_name(_) ->
    error.

get_entry_name(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_entry_name(Value), Value, Rest);
get_entry_name(_) ->
    error.

get_xattr_name(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_xattr_name(Value), Value, Rest);
get_xattr_name(_) ->
    error.

get_string(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_string(Value), Value, Rest);
get_string(_) ->
    error.

get_target(<<Size:16/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_target(Value), Value, Rest);
get_target(_) ->
    error.

get_data(<<Size:32/little, Value:Size/binary, Rest/binary>>) ->
    checked(is_data(Value), Value, Rest);
get_data(_) ->
    error.

get_qid(Bin0) ->
    maybe
        {ok, E1, Bin1} ?= get_u8(Bin0),
        {ok, E2, Bin2} ?= get_u32(Bin1),
        {ok, E3, Bin3} ?= get_u64(Bin2),
        {ok, {E1, E2, E3}, Bin3}
    end.

get_dirent(Bin0) ->
    maybe
        {ok, E1, Bin1} ?= get_qid(Bin0),
        {ok, E2, Bin2} ?= get_u64(Bin1),
        {ok, E3, Bin3} ?= get_u8(Bin2),
        {ok, E4, Bin4} ?= get_entry_name(Bin3),
        {ok, {E1, E2, E3, E4}, Bin4}
    end.

get_walk_names(<<Size:16/little, Rest/binary>>) when Size =< ?P9_MAXWELEM ->
    elements(fun get_walk_name/1, Size, Rest, []);
get_walk_names(_) ->
    error.

get_qids(<<Size:16/little, Rest/binary>>) when Size =< ?P9_MAXWELEM ->
    elements(fun get_qid/1, Size, Rest, []);
get_qids(_) ->
    error.

get_dirents(<<Size:32/little, Packed:Size/binary, Rest/binary>>) ->
    case packed_elements(fun get_dirent/1, Packed, ?P9_DIRENTS_MAX, []) of
        {ok, Values} -> {ok, Values, Rest};
        error -> error
    end;
get_dirents(_) ->
    error.

get_attr(Bin0) ->
    maybe
        {ok, Valid, Bin1} ?= get_u64(Bin0),
        {ok, Qid, Bin2} ?= get_qid(Bin1),
        {ok, Mode, Bin3} ?= get_u32(Bin2),
        {ok, Uid, Bin4} ?= get_u32(Bin3),
        {ok, Gid, Bin5} ?= get_u32(Bin4),
        {ok, Nlink, Bin6} ?= get_u64(Bin5),
        {ok, Rdev, Bin7} ?= get_u64(Bin6),
        {ok, Size, Bin8} ?= get_u64(Bin7),
        {ok, Blksize, Bin9} ?= get_u64(Bin8),
        {ok, Blocks, Bin10} ?= get_u64(Bin9),
        {ok, AtimeSec, Bin11} ?= get_u64(Bin10),
        {ok, AtimeNsec, Bin12} ?= get_u64(Bin11),
        {ok, MtimeSec, Bin13} ?= get_u64(Bin12),
        {ok, MtimeNsec, Bin14} ?= get_u64(Bin13),
        {ok, CtimeSec, Bin15} ?= get_u64(Bin14),
        {ok, CtimeNsec, Bin16} ?= get_u64(Bin15),
        {ok, BtimeSec, Bin17} ?= get_u64(Bin16),
        {ok, BtimeNsec, Bin18} ?= get_u64(Bin17),
        {ok, Gen, Bin19} ?= get_u64(Bin18),
        {ok, DataVersion, Bin20} ?= get_u64(Bin19),
        {ok, #{valid => Valid, qid => Qid, mode => Mode, uid => Uid, gid => Gid,
               nlink => Nlink, rdev => Rdev, size => Size, blksize => Blksize,
               blocks => Blocks, atime_sec => AtimeSec, atime_nsec => AtimeNsec,
               mtime_sec => MtimeSec, mtime_nsec => MtimeNsec, ctime_sec => CtimeSec,
               ctime_nsec => CtimeNsec, btime_sec => BtimeSec, btime_nsec => BtimeNsec,
               gen => Gen, data_version => DataVersion},
         Bin20}
    end.

get_set_attr(Bin0) ->
    maybe
        {ok, Valid, Bin1} ?= get_u32(Bin0),
        {ok, Mode, Bin2} ?= get_u32(Bin1),
        {ok, Uid, Bin3} ?= get_u32(Bin2),
        {ok, Gid, Bin4} ?= get_u32(Bin3),
        {ok, Size, Bin5} ?= get_u64(Bin4),
        {ok, AtimeSec, Bin6} ?= get_u64(Bin5),
        {ok, AtimeNsec, Bin7} ?= get_u64(Bin6),
        {ok, MtimeSec, Bin8} ?= get_u64(Bin7),
        {ok, MtimeNsec, Bin9} ?= get_u64(Bin8),
        {ok, #{valid => Valid, mode => Mode, uid => Uid, gid => Gid, size => Size,
               atime_sec => AtimeSec, atime_nsec => AtimeNsec, mtime_sec => MtimeSec,
               mtime_nsec => MtimeNsec},
         Bin9}
    end.

get_statfs(Bin0) ->
    maybe
        {ok, Type, Bin1} ?= get_u32(Bin0),
        {ok, Bsize, Bin2} ?= get_u32(Bin1),
        {ok, Blocks, Bin3} ?= get_u64(Bin2),
        {ok, Bfree, Bin4} ?= get_u64(Bin3),
        {ok, Bavail, Bin5} ?= get_u64(Bin4),
        {ok, Files, Bin6} ?= get_u64(Bin5),
        {ok, Ffree, Bin7} ?= get_u64(Bin6),
        {ok, Fsid, Bin8} ?= get_u64(Bin7),
        {ok, Namelen, Bin9} ?= get_u32(Bin8),
        {ok, #{type => Type, bsize => Bsize, blocks => Blocks, bfree => Bfree,
               bavail => Bavail, files => Files, ffree => Ffree, fsid => Fsid,
               namelen => Namelen},
         Bin9}
    end.

%% Each compound kind's bytes, for a value its kind check accepts.
put_qid({E1, E2, E3}) ->
    <<E1:8, E2:32/little, E3:64/little>>.

put_dirent({E1, E2, E3, E4}) ->
    <<(put_qid(E1))/binary, E2:64/little, E3:8, (byte_size(E4)):16/little, E4/binary>>.

put_walk_names(Values) ->
    <<(length(Values)):16/little,
      (<< <<(byte_size(Value)):16/little, Value/binary>> || Value <- Values >>)/binary>>.

put_qids(Values) ->
    <<(length(Values)):16/little,
      (<< <<(put_qid(Value))/binary>> || Value <- Values >>)/binary>>.

put_dirents(Values) ->
    Packed = << <<(put_dirent(Value))/binary>> || Value <- Values >>,
    <<(byte_size(Packed)):32/little, Packed/binary>>.

put_attr(#{valid := Valid, qid := Qid, mode := Mode, uid := Uid, gid := Gid, nlink := Nlink,
           rdev := Rdev, size := Size, blksize := Blksize, blocks := Blocks,
           atime_sec := AtimeSec, atime_nsec := AtimeNsec, mtime_sec := MtimeSec,
           mtime_nsec := MtimeNsec, ctime_sec := CtimeSec, ctime_nsec := CtimeNsec,
           btime_sec := BtimeSec, btime_nsec := BtimeNsec, gen := Gen,
           data_version := DataVersion}) ->
    <<Valid:64/little, (put_qid(Qid))/binary, Mode:32/little, Uid:32/little, Gid:32/little,
        Nlink:64/little, Rdev:64/little, Size:64/little, Blksize:64/little, Blocks:64/little,
        AtimeSec:64/little, AtimeNsec:64/little, MtimeSec:64/little, MtimeNsec:64/little,
        CtimeSec:64/little, CtimeNsec:64/little, BtimeSec:64/little, BtimeNsec:64/little,
        Gen:64/little, DataVersion:64/little>>.

put_set_attr(#{valid := Valid, mode := Mode, uid := Uid, gid := Gid, size := Size,
               atime_sec := AtimeSec, atime_nsec := AtimeNsec, mtime_sec := MtimeSec,
               mtime_nsec := MtimeNsec}) ->
    <<Valid:32/little, Mode:32/little, Uid:32/little, Gid:32/little, Size:64/little,
        AtimeSec:64/little, AtimeNsec:64/little, MtimeSec:64/little, MtimeNsec:64/little>>.

put_statfs(#{type := Type, bsize := Bsize, blocks := Blocks, bfree := Bfree,
             bavail := Bavail, files := Files, ffree := Ffree, fsid := Fsid,
             namelen := Namelen}) ->
    <<Type:32/little, Bsize:32/little, Blocks:64/little, Bfree:64/little, Bavail:64/little,
        Files:64/little, Ffree:64/little, Fsid:64/little, Namelen:32/little>>.

%% The field kinds of the table.
is_u8(Value) ->
    is_integer(Value) andalso Value >= 0 andalso Value =< 16#ff.

is_u16(Value) ->
    is_integer(Value) andalso Value >= 0 andalso Value =< 16#ffff.

is_u32(Value) ->
    is_integer(Value) andalso Value >= 0 andalso Value =< 16#ffffffff.

is_u64(Value) ->
    is_integer(Value) andalso Value >= 0 andalso Value =< 16#ffffffffffffffff.

%% fid: a u32 other than ?P9_NOFID.
is_fid(Value) ->
    is_u32(Value) andalso Value =/= ?P9_NOFID.

%% io_count: a u32 of at most ?P9_IO_MAX.
is_io_count(Value) ->
    is_u32(Value) andalso Value =< ?P9_IO_MAX.

%% xattr_size: a u64 of at most ?P9_XATTR_MAX.
is_xattr_size(Value) ->
    is_u64(Value) andalso Value =< ?P9_XATTR_MAX.

%% unlink_flags: 0 or ?P9_AT_REMOVEDIR.
is_unlink_flags(Value) ->
    Value =:= 0 orelse Value =:= ?P9_AT_REMOVEDIR.

%% at: a u64 or unknown.
is_at(Value) ->
    Value =:= unknown orelse is_u64(Value).

%% name: at most ?NAME_MAX bytes of UTF-8; refuses NUL, "/", empty, ".", "..".
is_name(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?NAME_MAX
        andalso Value =/= <<>>
        andalso Value =/= <<".">>
        andalso Value =/= <<"..">>
        andalso binary:match(Value, [<<0>>, <<"/">>]) =:= nomatch
        andalso is_utf8(Value).

%% walk_name: at most ?NAME_MAX bytes of UTF-8; refuses NUL, "/", empty, ".".
is_walk_name(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?NAME_MAX
        andalso Value =/= <<>>
        andalso Value =/= <<".">>
        andalso binary:match(Value, [<<0>>, <<"/">>]) =:= nomatch
        andalso is_utf8(Value).

%% entry_name: at most ?NAME_MAX bytes of UTF-8; refuses NUL, "/", empty.
is_entry_name(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?NAME_MAX
        andalso Value =/= <<>>
        andalso binary:match(Value, [<<0>>, <<"/">>]) =:= nomatch
        andalso is_utf8(Value).

%% xattr_name: at most ?NAME_MAX bytes of UTF-8; refuses NUL, "/".
is_xattr_name(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?NAME_MAX
        andalso binary:match(Value, [<<0>>, <<"/">>]) =:= nomatch
        andalso is_utf8(Value).

%% string: at most ?P9_STRING_MAX bytes of UTF-8; refuses NUL.
is_string(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?P9_STRING_MAX
        andalso binary:match(Value, [<<0>>]) =:= nomatch
        andalso is_utf8(Value).

%% target: at most ?P9_SYMLINK_MAX bytes; refuses NUL.
is_target(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?P9_SYMLINK_MAX
        andalso binary:match(Value, [<<0>>]) =:= nomatch.

%% data: at most ?P9_IO_MAX bytes.
is_data(Value) ->
    is_binary(Value)
        andalso byte_size(Value) =< ?P9_IO_MAX.

%% qid: {u8, u32, u64}.
is_qid({E1, E2, E3}) ->
    is_u8(E1)
        andalso is_u32(E2)
        andalso is_u64(E3);
is_qid(_) ->
    false.

%% dirent: {qid, u64, u8, entry_name}.
is_dirent({E1, E2, E3, E4}) ->
    is_qid(E1)
        andalso is_u64(E2)
        andalso is_u8(E3)
        andalso is_entry_name(E4);
is_dirent(_) ->
    false.

%% walk_names: a list of at most ?P9_MAXWELEM walk_name.
is_walk_names(Value) ->
    is_list_of(fun is_walk_name/1, Value, ?P9_MAXWELEM).

%% qids: a list of at most ?P9_MAXWELEM qid.
is_qids(Value) ->
    is_list_of(fun is_qid/1, Value, ?P9_MAXWELEM).

%% dirents: a list of at most ?P9_DIRENTS_MAX dirent.
is_dirents(Value) ->
    is_list_of(fun is_dirent/1, Value, ?P9_DIRENTS_MAX).

%% attr: a map of exactly the keys
%%   valid, qid, mode, uid, gid, nlink, rdev, size, blksize, blocks, atime_sec, atime_nsec,
%%   mtime_sec, mtime_nsec, ctime_sec, ctime_nsec, btime_sec, btime_nsec, gen, data_version.
is_attr(#{valid := Valid, qid := Qid, mode := Mode, uid := Uid,
          gid := Gid, nlink := Nlink, rdev := Rdev, size := Size,
          blksize := Blksize, blocks := Blocks, atime_sec := AtimeSec, atime_nsec := AtimeNsec,
          mtime_sec := MtimeSec, mtime_nsec := MtimeNsec, ctime_sec := CtimeSec, ctime_nsec := CtimeNsec,
          btime_sec := BtimeSec, btime_nsec := BtimeNsec, gen := Gen, data_version := DataVersion} = Value) when map_size(Value) =:= 20 ->
    is_u64(Valid)
        andalso is_qid(Qid)
        andalso is_u32(Mode)
        andalso is_u32(Uid)
        andalso is_u32(Gid)
        andalso is_u64(Nlink)
        andalso is_u64(Rdev)
        andalso is_u64(Size)
        andalso is_u64(Blksize)
        andalso is_u64(Blocks)
        andalso is_u64(AtimeSec)
        andalso is_u64(AtimeNsec)
        andalso is_u64(MtimeSec)
        andalso is_u64(MtimeNsec)
        andalso is_u64(CtimeSec)
        andalso is_u64(CtimeNsec)
        andalso is_u64(BtimeSec)
        andalso is_u64(BtimeNsec)
        andalso is_u64(Gen)
        andalso is_u64(DataVersion);
is_attr(_) ->
    false.

%% set_attr: a map of exactly the keys
%%   valid, mode, uid, gid, size, atime_sec, atime_nsec, mtime_sec, mtime_nsec.
is_set_attr(#{valid := Valid, mode := Mode, uid := Uid, gid := Gid,
              size := Size, atime_sec := AtimeSec, atime_nsec := AtimeNsec, mtime_sec := MtimeSec,
              mtime_nsec := MtimeNsec} = Value) when map_size(Value) =:= 9 ->
    is_u32(Valid)
        andalso is_u32(Mode)
        andalso is_u32(Uid)
        andalso is_u32(Gid)
        andalso is_u64(Size)
        andalso is_u64(AtimeSec)
        andalso is_u64(AtimeNsec)
        andalso is_u64(MtimeSec)
        andalso is_u64(MtimeNsec);
is_set_attr(_) ->
    false.

%% statfs: a map of exactly the keys
%%   type, bsize, blocks, bfree, bavail, files, ffree, fsid, namelen.
is_statfs(#{type := Type, bsize := Bsize, blocks := Blocks, bfree := Bfree,
            bavail := Bavail, files := Files, ffree := Ffree, fsid := Fsid,
            namelen := Namelen} = Value) when map_size(Value) =:= 9 ->
    is_u32(Type)
        andalso is_u32(Bsize)
        andalso is_u64(Blocks)
        andalso is_u64(Bfree)
        andalso is_u64(Bavail)
        andalso is_u64(Files)
        andalso is_u64(Ffree)
        andalso is_u64(Fsid)
        andalso is_u32(Namelen);
is_statfs(_) ->
    false.

%% Walks at most Left elements of a proper list, and refuses any other term.
is_list_of(_, [], _) ->
    true;
is_list_of(Check, [Head | Tail], Left) when Left > 0 ->
    Check(Head) andalso is_list_of(Check, Tail, Left - 1);
is_list_of(_, _, _) ->
    false.

%% UTF-8 as the binary syntax matches it: no overlong form, surrogate or code point
%% past 16#10ffff.
is_utf8(<<_/utf8, Rest/binary>>) ->
    is_utf8(Rest);
is_utf8(<<>>) ->
    true;
is_utf8(_) ->
    false.

%% A value read from the bytes, kept when its kind's check accepts it.
checked(true, Value, Rest) ->
    {ok, Value, Rest};
checked(false, _, _) ->
    error.

%% Count elements read one after another.
elements(_, 0, Rest, Values) ->
    {ok, lists:reverse(Values), Rest};
elements(Get, Count, Bin0, Values) ->
    case Get(Bin0) of
        {ok, Value, Rest} -> elements(Get, Count - 1, Rest, [Value | Values]);
        error -> error
    end.

%% Elements read until the packed bytes end exactly, at most Left of them.
packed_elements(_, <<>>, _, Values) ->
    {ok, lists:reverse(Values)};
packed_elements(Get, Bin0, Left, Values) when Left > 0 ->
    case Get(Bin0) of
        {ok, Value, Rest} -> packed_elements(Get, Rest, Left - 1, [Value | Values]);
        error -> error
    end;
packed_elements(_, _, _, _) ->
    error.
